import{_ as e,o as i,c as t,al as a}from"./chunks/framework.7vp1BMOE.js";const g=JSON.parse('{"title":"Integration Testing for the PX4 ROS 2 Interface Library","description":"","frontmatter":{},"headers":[],"relativePath":"en/test_and_ci/integration_testing_px4_ros2_interface.md","filePath":"en/test_and_ci/integration_testing_px4_ros2_interface.md"}'),n={name:"en/test_and_ci/integration_testing_px4_ros2_interface.md"};function r(o,s,l,h,p,c){return i(),t("div",null,[...s[0]||(s[0]=[a(`<h1 id="integration-testing-for-the-px4-ros-2-interface-library" tabindex="-1">Integration Testing for the PX4 ROS 2 Interface Library <a class="header-anchor" href="#integration-testing-for-the-px4-ros-2-interface-library" aria-label="Permalink to &quot;Integration Testing for the PX4 ROS 2 Interface Library&quot;">​</a></h1><p>This topic outlines the integration tests for the <a href="./../ros2/px4_ros2_interface_lib">PX4 ROS 2 Interface Library</a>.</p><p>These test that mode registration, failsafes, and mode replacement, work as expected.</p><h2 id="ci-testing" tabindex="-1">CI Testing <a class="header-anchor" href="#ci-testing" aria-label="Permalink to &quot;CI Testing&quot;">​</a></h2><p>When opening a pull request to PX4, CI runs the library integration tests. It builds the pull request&#39;s PX4 firmware and a matching ROS workspace, then runs the tests using <a href="./../sim_sih/">SIH</a>. SIH runs the physics simulation inside PX4 and does not require Gazebo Classic or Gazebo Harmonic.</p><h2 id="running-tests-locally" tabindex="-1">Running Tests Locally <a class="header-anchor" href="#running-tests-locally" aria-label="Permalink to &quot;Running Tests Locally&quot;">​</a></h2><p>Follow <a href="./../dev_setup/sitl_container_builds#testing-a-px4-checkout-with-ros">Testing A PX4 Checkout With ROS</a> to build <code>px4_sitl_sih</code> and a matching ROS workspace. Run the following commands from the PX4 repository root, inside the ROS development environment:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/px4_ros2_ci/install/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./test/ros_test_runner.py</span></span></code></pre></div><p>If you used another workspace location, source its <code>install/setup.bash</code> instead. The runner defaults to <code>test/ros_tests/config-sih.json</code> and <code>build/px4_sitl_sih/</code>, matching CI. The SIH configuration selects the <code>quadx</code> model for all three integration suites. SIH does not support the runner&#39;s <code>--gui</code> option.</p><p>And to run only a single case:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./test/ros_test_runner.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --verbose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --case</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">cas</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>You can list the available test cases with:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./test/ros_test_runner.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list-cases</span></span></code></pre></div><h2 id="legacy-gazebo-classic-testing" tabindex="-1">Legacy Gazebo Classic Testing <a class="header-anchor" href="#legacy-gazebo-classic-testing" aria-label="Permalink to &quot;Legacy Gazebo Classic Testing&quot;">​</a></h2><p>For an existing Gazebo Classic setup, select both its configuration and firmware build directory explicitly:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./test/ros_test_runner.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --config-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/ros_tests/config.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --build-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/px4_sitl_default/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iris</span></span></code></pre></div><p>This requires separately built Gazebo Classic plugins and matching ROS sources. The Gazebo Harmonic containers do not provide Gazebo Classic.</p>`,17)])])}const k=e(n,[["render",r]]);export{g as __pageData,k as default};
